def get_demo_response(prompt: str) -> str:
    """
    Return a pre-canned JSON response based on keywords in the prompt.
    Always prepends the DEMO_NOTICE so it is unambiguous.
    """
    prompt_lower = prompt.lower()

    # Pick the most relevant category
    if any(kw in prompt_lower for kw in ["dns", "network", "resolve", "ping", "connection", "interface"]):
        data = _DEMO_RESPONSES["networking"]
    elif any(kw in prompt_lower for kw in ["apt", "package", "install", "repository", "dnf", "yum", "pacman"]):
        data = _DEMO_RESPONSES["package_management"]
    else:
        data = _DEMO_RESPONSES["default"]

    # Shallow copy and prepend demo notice to limitations
    result = dict(data)
    result["limitations"] = DEMO_NOTICE + " " + result.get("limitations", "")

    return json.dumps(result, indent=2)


def get_demo_responses_for_all_strategies() -> dict[str, str]:
    """Return demo responses keyed by strategy name for the comparison dashboard."""
    strategies = ["zero_shot", "role_based", "few_shot", "constraint_based", "iterative_refinement"]
    result = {}
    for strategy in strategies:
        result[strategy] = get_demo_response(f"demo request for {strategy}")
    return result
